#!/usr/bin/env python3
"""Cargo benchmark RUSTC_WRAPPER: serialize TiKV libs; preserve native flags."""

from __future__ import annotations

from datetime import datetime, timezone
import json
import os
from pathlib import Path
import sys


LOG = Path("/tmp/tikv-4239-final-unit-rustc-wrapper.log")


def compilation_identity(arguments: list[str]) -> tuple[str | None, bool, set[str]]:
    if not arguments:
        raise ValueError("Cargo must pass the rustc executable as the first argument")
    crate_name = None
    crate_types = set()
    for index, argument in enumerate(arguments[1:], start=1):
        if argument == "--crate-name" and index + 1 < len(arguments):
            crate_name = arguments[index + 1]
        elif argument.startswith("--crate-name="):
            crate_name = argument.split("=", 1)[1]
        elif argument == "--crate-type" and index + 1 < len(arguments):
            crate_types.update(arguments[index + 1].split(","))
        elif argument.startswith("--crate-type="):
            crate_types.update(argument.split("=", 1)[1].split(","))
    return crate_name, "--test" in arguments[1:], crate_types


def adjust_arguments(arguments: list[str]) -> tuple[list[str], bool]:
    """Preserve rustc, arguments and order; append only the requested override."""
    crate_name, is_test, crate_types = compilation_identity(arguments)
    argv = list(arguments)
    if crate_name in {"raftstore", "tikv"} and is_test:
        argv.extend(["-Ccodegen-units=16", "-Zno-parallel-backend"])
    elif crate_name == "tikv" and not is_test and crate_types.intersection({"lib", "rlib"}):
        # Keep Cargo's explicit hot-path CGU setting. Native/dependency flags
        # remain untouched; only serialize this crate's LLVM backend.
        argv.append("-Zno-parallel-backend")
    return argv, argv != arguments


def main() -> None:
    original = sys.argv[1:]
    argv, changed = adjust_arguments(original)
    if changed:
        crate_name, is_test, _ = compilation_identity(original)
        line = json.dumps(
            {
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "pid": os.getpid(),
                "crate_name": crate_name,
                "test": is_test,
                "appended": argv[len(original):],
                "rustc": argv[0],
                "argv_count": len(argv),
            },
            separators=(",", ":"),
        ) + "\n"
        descriptor = os.open(LOG, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        try:
            os.write(descriptor, line.encode("utf-8"))
        finally:
            os.close(descriptor)
    # execv preserves the current environment, cwd and inherited descriptors.
    # No shell, quoting interpretation, environment replacement, or subprocess.
    os.execv(argv[0], argv)


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError) as error:
        print(f"bench-rustc-wrapper: {error}", file=sys.stderr)
        sys.exit(2)

