// Install at components/scanner-reuse-verification/bench.rs.
// Build with -p tests -p scanner-reuse-verification and only this bench target.
// In addition to the selective profile, pass:
// --config 'profile.test.package.scanner-reuse-verification.opt-level=3'
// --config 'profile.test.package.scanner-reuse-verification.debug=0'
// The existing profile optimizes the tests package, not this new harness.
// Build once and execute the exact binary in F/R/R/F order. Direct execution
// must include --bench, or Criterion 0.3.5 enters test mode without measurements.

#[path = "../../tests/benches/coprocessor_executors/multi_range_scan.rs"]
mod multi_range_scan;

fn main() {
    let mut criterion = criterion::Criterion::default()
        .with_measurement(criterion_cpu_time::PosixTime::UserTime)
        .configure_from_args();
    multi_range_scan::bench(&mut criterion);
    criterion.final_summary();
}

